package de.corporate.lc.lc.service;
import de.corporate.lc.lc.domain.LetterOfCredit;import de.corporate.lc.lc.repository.*;import de.corporate.lc.swift.Mt707Parser;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class AmendmentServiceTest{private final AmendmentService service=new AmendmentService(mock(AmendmentRepository.class),mock(LetterOfCreditRepository.class),new Mt707Parser());
 @Test void addsAndDeletesDocumentRequirements(){LetterOfCredit lc=new LetterOfCredit();lc.setRequiredDocuments(new ArrayList<>(List.of("SIGNED COMMERCIAL INVOICE","OLD PACKING LIST")));service.applyDocumentChanges(lc,"/DELETE/OLD PACKING LIST\n/ADD/PACKING LIST IN 3 COPIES");assertThat(lc.getRequiredDocuments()).containsExactly("SIGNED COMMERCIAL INVOICE","PACKING LIST IN 3 COPIES");}
 @Test void replacesAllRequirementsOnlyWhenExplicit(){LetterOfCredit lc=new LetterOfCredit();lc.setRequiredDocuments(new ArrayList<>(List.of("OLD INVOICE")));service.applyDocumentChanges(lc,"/REPALL/\nNEW INVOICE\nPACKING LIST");assertThat(lc.getRequiredDocuments()).containsExactly("NEW INVOICE","PACKING LIST");}
 @Test void leavesAmbiguousUnmarkedTextForManualReview(){LetterOfCredit lc=new LetterOfCredit();lc.setRequiredDocuments(new ArrayList<>(List.of("ORIGINAL INVOICE")));service.applyDocumentChanges(lc,"DOCUMENTS ARE CHANGED AS AGREED");assertThat(lc.getRequiredDocuments()).containsExactly("ORIGINAL INVOICE");}
 @Test void replacesEffectiveGoodsDescription(){LetterOfCredit lc=new LetterOfCredit();lc.setRawMessage(":20:LC-1\n:45A:OLD MACHINES");service.applyGoodsChanges(lc,"/REPALL/\nNEW INDUSTRIAL PUMPS");assertThat(lc.getAdditionalFields()).containsEntry("45A - gültige Warenbeschreibung","NEW INDUSTRIAL PUMPS");}
 @Test void addsAndDeletesGoodsLines(){LetterOfCredit lc=new LetterOfCredit();lc.setRawMessage(":45A:OLD MACHINES\nSPARE PARTS");service.applyGoodsChanges(lc,"/DELETE/OLD MACHINES\n/ADD/NEW PUMPS");assertThat(lc.getAdditionalFields().get("45A - gültige Warenbeschreibung")).isEqualTo("SPARE PARTS\nNEW PUMPS");}}
